',2,0);
CREATE TABLE private_keys (item INTEGER, ownPass INTEGER, private TEXT, FOREIGN KEY (item) REFERENCES items (id));
INSERT INTO "private_keys" VALUES(1,0,'');
INSERT INTO "private_keys" VALUES(2,0,'');
CREATE TABLE public_keys (item INTEGER, type VARCHAR(32), hash INTEGER, len INTEGER, "public" TEXT, FOREIGN KEY (item) REFERENCES items (id));
INSERT INTO "public_keys" VALUES(1,'ML-DSA-65',804931888,15616,'');
INSERT INTO "public_keys" VALUES(2,'ML-DSA-65',788873648,15616,'');
CREATE TABLE requests (item INTEGER, hash INTEGER, signed INTEGER, request TEXT, FOREIGN KEY (item) REFERENCES items (id));
CREATE TABLE revocations (caId INTEGER, serial VARCHAR(64), date CHAR(15), invaldate CHAR(15), crlNo INTEGER, reasonBit INTEGER, FOREIGN KEY (caId) REFERENCES items (id));
CREATE TABLE settings (key_ CHAR(20) UNIQUE, value TEXT);
INSERT INTO "settings" VALUES('schema','8');
INSERT INTO "settings" VALUES('bxc_schema','3');
